FRAGMENTS = {
    "block-section-introduction-1": "Заклинання Слідопита — цікава суміш бафів і утилітарних варіантів із жменею заклинань прямої шкоди й лікування. Більшість заклинань узято зі списку заклинань Друїда, хоч у Слідопита є й кілька унікальних, як-от <<Hunter's Mark>>, а нерідко заклинання, спільні з друїдом, — найгірші варіанти Слідопита, тоді як унікальні для Слідопита — найкращі.",
    "block-section-introduction-2": "Вибір заклинань Слідопита також сильно обмежують уявлення розробників гри про те, ким є слідопит і куди він ходить у пригоди. Заклинання сильно тяжіють до боїв у лісах (чи в лісоподібних місцях, як-от сади — по суті, будь-де, де є дерева й інша рясна рослинність), а це означає, що коли ви бʼєтеся деінде, ваші варіанти заклинань обмежені ще більше.",
    "block-section-introduction-3": "Є й виразний ухил на користь дальнього бою: слідопити-стрільці з нетерпінням чекають на <<Swift Quiver>> на 5-му рівні заклинань, а слідопити ближнього бою отримують <<Steel Wind Strike>>, якому абсолютно байдуже, наскільки ви добрі в ближньому бою, бо це заклинальна атака з власною шкодою, і слідопити-стрільці можуть користуватися ним так само добре. Сподіваюся, у майбутньому зʼявляться нові варіанти, але зважаючи на те, що в «Довіднику Занатара про все»{{Xanathar’s Guide to Everything}} слідопит отримав лише 6 нових заклинань, я не оптимістичний.",

    "block-section-cantrips-1": "Бойовий Стиль{{Fighting Style}} <<q:Druidic Warrior>> дає змогу брати замовляння. Щоб виправдати втрату інших бойових стилів заради Друїдичного воїна, ваш вибір замовлянь у контексті решти збірки має компенсувати цю втрату й відповісти на запитання: «Чому б просто не зіграти за друїда?»",
    "block-section-cantrips-2": "Оскільки замовляння зменшують вашу залежність від Сили чи Спритності, вважатимемо, що ви максимально підвищуєте Мудрість, обираючи замовляння. На жаль, оскільки Слідопит — бойовий клас, а ефективних наступальних варіантів, окрім цих замовлянь, у вас не буде, утилітарні заклинання виправдати важче.",

    "block-section-cantrips-3/item/0": "<<Control Flames>> ^^(^^[[1|EEPC / XGtE]]^^)^^: украй розчаровує як утилітарний варіант.",
    "block-section-cantrips-3/item/1": "<<Create Bonfire>> ^^(^^[[1|EEPC / XGtE]]^^)^^: добра шкода й дешевий контроль території, але вимагає Концентрації, тож конкуруватиме з багатьма цікавішими речами, які роблять слідопити.",
    "block-section-cantrips-3/item/2": "<<Druidcraft>> ^^(^^[[1|PHB]]^^)^^: украй розчаровує як утилітарний варіант.",
    "block-section-cantrips-3/item/5": "<<Gust>> ^^(^^[[1|EEPC / XGtE]]^^)^^: це заклинання майже цілком марне.",
    "block-section-cantrips-3/item/7": "<<Magic Stone>> ^^(^^[[1|EEPC / XGtE]]^^)^^: 1к6+Мудрість шкоди. У вас є <<q:Extra Attack|Додаткова атака>>, а це не витрачає Концентрацію, тож може працювати з <<Hunter's Mark|Мисливською міткою>> чи <<q:Favored Foe|Міченим ворогом>>. Це майже так само добре, як слідопит на Спритності зі зброєю, але ви відмовляєтеся від переваг бойового стилю заради вищої Мудрості, а ще постійно платите бонусною дією за використання, що сильно обмежить вашу економіку дій. Підкласам, що мають інше застосування бонусної дії, варто шукати щось інше.",
    "block-section-cantrips-3/item/9": "<<Mold Earth>> ^^(^^[[1|EEPC / XGtE]]^^)^^: розчаровує як утилітарний варіант. Ніхто не може домовитися, що саме вважати «пухкою землею», тож зробити його надійним важко.",
    "block-section-cantrips-3/item/10": "<<Poison Spray>> ^^(^^[[1|PHB]]^^)^^: висока шкода, але все інше в ньому погане.",
    "block-section-cantrips-3/item/11": "<<Primal Savagery>> ^^(^^[[1|XGtE]]^^)^^: <<Shillelagh>> буде ефективнішим, тож беріть <<Shillelagh>>, якщо вам украй не потрібна вільна рука.",
    "block-section-cantrips-3/item/12": "<<Produce Flame>> ^^(^^[[1|PHB]]^^)^^: ваш основний варіант дальньої шкоди в більшості випадків. Дальність більша, ніж у <<Thorn Whip|Тернового батога>> (хоч це не обовʼязково робить його кращим). Якщо ви берете це як основний варіант атаки, вам не слід брати <<q:Druidic Warrior|Друїдичного воїна>>.",
    "block-section-cantrips-3/item/13": "<<Resistance>> ^^(^^[[1|PHB]]^^)^^: погане.",
    "block-section-cantrips-3/item/14": "<<Shape Water>> ^^(^^[[1|EEPC / XGtE]]^^)^^: дивіться наш [[2|практичний гайд зі «<<c:Shape Water>>»]], щоб дізнатися більше про те, наскільки чудове <<Shape Water>>.",
    "block-section-cantrips-3/item/15": "<<Shillelagh>> ^^(^^[[1|PHB]]^^)^^: по суті, причина, з якої існує <<q:Druidic Warrior>>. Багато в чому це замовляння ідеально ілюструє угоду, на яку ви йдете з Друїдичним воїном. Ви можете перетворити дубинку чи палицю на еквівалент довгого меча, використовуючи модифікатор Мудрості. Подумайте й про <<q:Polearm Master|Майстра древкової зброї>>.",
    "block-section-cantrips-3/item/16": "<<Thorn Whip>> ^^(^^[[1|PHB]]^^)^^: шкода пристойна, але справжня принада — ефект затягування. 10 футів можуть здаватися небагатьма, але цього досить, щоб стягувати ворогів з уступів, затягувати низько літаючих ворогів у ближній бій, затягувати ворогів в ефект контролю території на кшталт <<Create Bonfire>>, витягувати ворогів із захоплення, а в скруті можна витягти з небезпечного місця й союзника (хоч і ціною певної дружньої шкоди).",
    "block-section-cantrips-3/item/17": "<<Thunderclap>> ^^(^^[[1|EEPC / XGtE]]^^)^^: завдавати шкоди кожній істоті в межах 5 футів від вас — чудово, якщо ви в ближньому бою з численними ворогами. Навіть із <<q:Extra Attack|Додатковою атакою>> проти трьох чи більше ворогів ви завдасте цим більше шкоди, ніж зброєю. Дивіться нашу статтю про [[2|ближні замовляння проти Додаткової атаки]], де розібрано математику порівняння ближніх замовлянь зі звичайними атаками бойових класів. Єдина проблема — ряткидок Статури, але це все одно чудово.",

    "block-section-spells-1-1/item/0": "<<Absorb Elements>> ^^(^^[[1|XGtE]]^^)^^: ви отримуєте чаротворство пізніше й повільніше за будь-кого іншого, тож у вас дуже мало варіантів захисту від нефізичної шкоди. Це заклинання розвʼяже цю проблему, але швидко зʼїсть ваші слоти заклинань, тож обовʼязково усувайте джерело шкоди від стихій якомога швидше, щоб не витратити слоти надто швидко. Найбільша складність <<Absorb Elements>> у тому, що воно має Соматичні компоненти, які потребують вільної руки. За замовчуванням це означає, що збірки з боєм двома зброями й збірки з мечем і щитом не зможуть ним користуватися, якщо ви не будете наполегливо діставати й ховати зброю, що і ускладнює принагідні атаки, і дозволяє використовувати <<Absorb Elements>> лише раз на два раунди. На жаль, єдиний обхід — [[2|«Бойовий заклинатель»]]{{War Caster}}.",
    "block-section-spells-1-1/item/1": "<<Alarm>> ^^(^^[[1|PHB]]^^)^^: не варте одного з ваших обмежених відомих заклинань. Залиште це тому, хто вміє накладати ритуали.",
    "block-section-spells-1-1/item/3": "<<Beast Bond>> ^^(^^[[1|EEPC]]^^)^^: це справді працює лише з оригінальною версією <<m:Beast Master|Звіролова>> із «Книги гравця». Варіанти «Звір землі», «Звір моря» та «Звір неба» з «Казана Таші з усім» і драк-супутник <<m:Drakewarden|Вартового дракона>> мають Інтелект 8, через що заклинання автоматично провалюється. Якщо ви граєте за Звіролова з «Книги гравця» 2014 року, це чудово для компаньйонів, які ще не мають <<q:Pack Tactics|Тактики зграї>>.",
    "block-section-spells-1-1/item/4": "<<Cure Wounds>> ^^(^^[[1|PHB]]^^)^^: у слідопитів не так багато слотів заклинань, як у повних заклинателів, тож витрачати на лікування свої дорогоцінні кілька слотів може бути важко. Проте комусь у групі треба вміти лікувати головного цілителя, якщо той втратить свідомість. Але щойно ви зможете отримати <<Healing Spirit>>, розгляньте заміну цього заклинання.",
    "block-section-spells-1-1/item/5": "<<Detect Magic>> ^^(^^[[1|PHB]]^^)^^: в ідеалі цим займеться хтось у групі, хто може накласти більше заклинань, ніж ви, але інколи вибору насправді немає.",
    "block-section-spells-1-1/item/7": "<<Ensnaring Strike>> ^^(^^[[1|PHB]]^^)^^: майже ексклюзивне для Слідопитів, <<Ensnaring Strike>> — чудовий спосіб упоратися з одиночною ціллю, що завдає вам проблем, особливо якщо ціль — монстр ближнього бою. Зауважте, що його можна використати на відстані, тож лучники можуть обплутати ціль, а потім або виснажувати її, або перемкнути її увагу на інших ворогів. Це ряткидок Сили, тож більшість заклинателів і багато спритних ворогів матимуть із ним труднощі, але великі громили ближнього бою, імовірно, йому опиратимуться. Це також чудова відповідь літаючим ворогам, бо стан Скутий змушує істот, що літають немагічно, падати, тож якщо ви підстрілите грифона чи щось таке, він отримає купу шкоди від падіння. Після першого ряткидка, щоб вирватися, потрібні Дія й перевірка Сили (не ряткидок), а ціль щораунду отримує шкоду, тож вона захоче вирватися швидко. Шкода зростає лінійно з рівнем заклинання, тож це лишається потужним і ефективним використанням слота заклинань упродовж усієї вашої карʼєри.",
    "block-section-spells-1-1/item/8": "<<Entangle>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): чудове заклинання контролю території на будь-якому рівні. Ряткидки Сили, як правило, низькі в будь-якої істоти, що не є велетенським силачем, тож легко скувати навіть ворогів високих рівнів. Проте воно вимагає Концентрації, тож його непросто поєднувати з такими речами, як <<Hunter's Mark>>.",
    "block-section-spells-1-1/item/10": "<<Goodberry>> ^^(^^[[1|PHB]]^^)^^: чудовий ресурс і для лікування, і як утиліта. Друїд зазвичай може виділити одне підготовлене заклинання, щоб наприкінці дня вливати слоти заклинань у <<Goodberry>>, але слідопиту це може бути складніше, бо ви маєте таку малу кількість відомих заклинань. Проте якщо напередодні виходу в пригоду вкласти свої слоти заклинань у купу доброягід, ви отримаєте корисну подушку ХП, якою можна швидко підлікуватися після бою, не вдаючись до короткого відпочинку.",
    "block-section-spells-1-1/item/11": "<<Hail of Thorns>> ^^(^^[[1|PHB]]^^)^^: це не має бути основним варіантом, але це гарний спосіб упоратися з щільно зібраними групами слабких ворогів. Тільки не покладайтеся на нього надто сильно, бо воно швидко зʼїсть ваші слоти заклинань без великої віддачі.",
    "block-section-spells-1-1/item/12": "<<Hunter's Mark>> ^^(^^[[1|PHB]]^^)^^: хліб насущний Слідопита. Багато слідопитів проводитимуть більшу частину часу, концентруючись на <<Hunter's Mark|Мисливській мітці>>, поки зосереджують вогонь на одиночних ворогах, перш ніж перемкнутися на наступного. Тривалість 1 година (більше, якщо накласти заклинання на вищому рівні) означає, що з одного слота заклинань можна вичавити купу користі, але якщо ви не бʼєтеся на відстані, вам доведеться постійно перейматися ряткидками для підтримки Концентрації. Книги правил, що вийшли після «Книги гравця», запровадили низку альтернатив <<Hunter's Mark|Мисливської мітки>>. Додаткове класове уміння{{Optional Class Feature}} <<q:Favored Foe>> — по суті, послаблена версія <<Hunter's Mark|Мисливської мітки>> із власним запасом використань, який не їсть ваші слоти заклинань, а заклинання на кшталт <<Elemental Weapon|Стихійної зброї>> можуть дати схоже підсилення шкоди. <<Hunter's Mark>> лишається основним бойовим варіантом Слідопита, але це вже не єдиний визначальний спосіб слідопита бути вагомою загрозою в бою.",
    "block-section-spells-1-1/item/14": "<<Longstrider>> ^^(^^[[1|PHB]]^^)^^: додаткові 10 фт. руху завжди приємні, а тривалість 1 година означає, що ним можна втішатися довго з одного слота заклинань. Якщо ви граєте повільну расу чи просто хочете трохи більше маневровості, це чудове доповнення.",
    "block-section-spells-1-1/item/15": "<<Searing Smite>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): пристойний спосіб завдавати триваючої шкоди ворогові з поганими ряткидками Статури, у якого вам важко влучити (як-от заклинач із захисними бафами), але воно працює лише з атаками зброєю ближнього бою, вимагає Концентрації, а ваша СК ряткидка, імовірно, замала, щоб це було надійно в переважній більшості боїв.",
    "block-section-spells-1-1/item/18": "<<Zephyr Strike>> ^^(^^[[1|XGtE]]^^)^^: накладіть його бонусною дією, і ви отримаєте переваги Відступу. Якщо атакуєте, то отримаєте Перевагу на кубику на атаку, трохи додаткової шкоди *і* переваги Ривка. Це можна зробити лише раз, але якщо ви побудовані для бою на відстані й щось підійшло незручно близько, увімкніть його, відступіть на 5 фт., вистріліть, щоб висловити своє невдоволення, а потім тікайте.",

    "block-section-spells-2-1/item/0": "<<Aid>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): з тривалістю 8 годин і трьома цілями це класичний баф, який варто накладати буквально щодня. В ідеалі хочеться, щоб його накладав хтось інший, але якщо більше нікому, це добре заклинання, щоб закріпитися за ним, бо воно буквально завжди корисне. Час накладання <<Aid|Підтримки>> дозволяє користуватися цим заклинанням у бою, що незвично, але дає цікавий варіант. З трьома цілями й дальністю 30 футів це заклинання можна накласти, щоб одночасно підсилити й підлікувати союзників у бою. І поточні ХП цілей, і максимум ХП збільшуються, тож союзники на 0 ХП зцілюються на додачу до підвищеного максимуму ХП, і так <<Aid>> може виконувати схожу функцію з <<Mass Healing Word|Масовим цілющим словом>>. Однак оскільки заклинання не складаються самі із собою, цей трюк важко повторити. Доведеться накласти <<Aid|Підтримку>> знову слотами вищого рівня, що швидко може стати дорогим, тож <<Mass Healing Word>>, імовірно, краще, якщо <<Aid>> уже діє й якщо <<Mass Healing Word>> — варіант для вашої групи.",
    "block-section-spells-2-1/item/1": "<<Animal Messenger>> ^^(^^[[1|PHB]]^^)^^: ситуативне й менш надійне, ніж схожі заклинання на кшталт <<Sending>>, але воно й на рівень заклинання нижче за <<Sending>>. Якщо ви знаєте, що отримувач буде там, куди ви відправляєте повідомлення, це працює нормально. На жаль, отримувач не може відповісти. До всіх цих складнощів додається те, що воно просто надто ситуативне, щоб Слідопит міг його виправдати.",
    "block-section-spells-2-1/item/2": "<<Barkskin>> ^^(^^[[1|PHB]]^^)^^: до того часу, як ви зможете її накласти, у вас уже має бути більше КБ, ніж вона здатна дати.",
    "block-section-spells-2-1/item/4": "<<Cordon of Arrows>> ^^(^^[[1|PHB]]^^)^^: з часом накладання 1 Дія ви справді можете використати це в бою, але шкода дуже низька (порівняйте двічі 1к6+Спритність із сумарними 4к6), тож задум явно в тому, щоб влаштовувати засідки чи захищати місце, де ви відпочиваєте. На відміну від схожих варіантів на кшталт <<Alarm|Тривоги>> і <<Snare|Пастки>>, воно не створює помітного шуму, коли спрацьовує, тож розгляньте можливість прикріпити дзвіночок до кожної стріли після накладання заклинання.",
    "block-section-spells-2-1/item/6": "<<Enhance Ability>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): це легко надолужує розрив у навичках між Слідопитом і Пройдисвітом. Перевага на кубику не зовсім така ефективна, як <<q:Expertise|Експертиза>>, щойно ваш бонус майстерності сягає +4, але близько. Це також легкий основний баф у різних ситуаціях, коли ваш власний персонаж може бути неефективним, як-от накладання <<Enhance Ability>> (Харизма) на «обличчя» вашої групи.",
    "block-section-spells-2-1/item/7": "<<Gust of Wind>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): надто ситуативне, щоб вивчати його назавжди.",
    "block-section-spells-2-1/item/9": "<<Healing Spirit>> ^^(^^[[1|XGtE]]^^)^^: це заклинання було *суттєво* послаблене ерратою, виданою 2020 року. Обмеження в 1+модифікатор використань означає, що більшість слідопитів можуть розраховувати приблизно на 3–4 використання заклинання, що в сумі дає лише 3к6/4к6 лікування при накладанні на 2-му рівні. Це все одно краще за <<Cure Wounds>>, але недостатньо добре, щоб замінити лікування від короткого відпочинку, коли ваша група в скруті. Лікування зростає на 1к6 за кожен слот понад 2-й, тож його можна подвоїти, використавши слот 3-го рівня. Загалом не варто використовувати це під час бою, бо лікування недостатньо швидке й вимагає Концентрації, яку ви, можливо, присвячуєте <<Hunter's Mark|Мисливській мітці>>, але ця угода може бути виправданою, щоб не витрачати ще одне відоме заклинання на <<Cure Wounds>>.",
    "block-section-spells-2-1/item/10": "<<Lesser Restoration>> ^^(^^[[1|PHB]]^^)^^: корисне, але до того часу, як ви його отримаєте, у вас, сподіваємося, уже є клірик чи хтось, у кого воно вже давно.",
    "block-section-spells-2-1/item/11": "<<Locate Animals or Plants>> ^^(^^[[1|PHB]]^^)^^: дуже ситуативне. Ситуації, коли треба знайти певний вид рослини, зазвичай є важливим сюжетним моментом, а не рутинним завданням, і якщо вашому Майстру не дуже подобається такий сюжетний прийом, воно не варте відомого заклинання.",
    "block-section-spells-2-1/item/13": "<<Magic Weapon>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): якщо у вашій грі є магічні предмети, пропустіть це. Якщо ні, це величезне підсилення вашого DPR, що легко перевершує <<Hunter's Mark|Мисливську мітку>>, а ще усуває потребу перепризначати мітку бонусною дією. Переходьте на <<Elemental Weapon|Стихійну зброю>>, коли отримаєте заклинання 3-го рівня, але повертайтеся до <<Magic Weapon|Магічної зброї>>, коли отримаєте заклинання 4-го рівня.",
    "block-section-spells-2-1/item/14": "<<Pass Without Trace>> ^^(^^[[1|PHB]]^^)^^: +10 — це *величезний* бонус, якого легко вистачає, щоб перекрити жахливий бонус Спритності й Перешкоду на кубику від обладунку, тож уся ваша група може скрадатися. Тривалість 1 година теж чудова, але памʼятайте, що воно вимагає Концентрації.",
    "block-section-spells-2-1/item/16": "<<Silence>> ^^(^^[[1|PHB]]^^)^^: чудова і для непомітності, і для виведення з ладу ворожих заклинателів, які часто можуть уникнути небезпеки за допомогою заклинань на кшталт <<Misty Step|Туманного кроку>>, що мають лише Вербальні компоненти.",
    "block-section-spells-2-1/item/17": "<<Spike Growth>> ^^(^^[[1|PHB]]^^)^^: чудовий контроль території для заклинання такого низького рівня, і воно не дозволяє ряткидка. Це особливо добре в сутичках із великою кількістю ворогів ближнього бою.",
    "block-section-spells-2-1/item/18": "<<Summon Beast>> ^^(^^[[1|TCoE]]^^)^^ (необовʼязкове): надто залежить і від рівня заклинання, і від модифікатора заклинальної характеристики. Більшість слідопитів не матимуть Мудрості, щоб це підкріпити, а ті слідопити, які вкладаються в Мудрість, усе одно не отримують рівнів заклинань достатньо швидко, щоб звір лишався життєздатним у бою.",

    "block-section-spells-3-1/item/0": "<<Ashardalon's Stride>> ^^(^^[[1|FToD]]^^)^^: час накладання — бонусна дія, а шкода не дозволяє ряткидка. За задумом це схоже на <<Zephyr Strike>>, але ви отримуєте безкоштовну шкоду в обмін на значно вищий рівень заклинання. Шкода на цьому рівні, можливо, вже не така велика, але в сутичках із численними ворогами вона може швидко накопичуватися.",
    "block-section-spells-3-1/item/1": "<<Conjure Animals>> ^^(^^[[1|PHB]]^^)^^: зазвичай це чудове заклинання, але Слідопит отримує його так пізно, що воно цілком застаріле.",
    "block-section-spells-3-1/item/2": "<<Conjure Barrage>> ^^(^^[[1|PHB]]^^)^^: єдиний козир цього заклинання — величезний конус 60 футів. 3к8 шкоди разом із вашою відносно поганою СК ряткидка означають, що більшість ворогів, імовірно, пройдуть ряткидок і отримають у середньому лише 6,75 шкоди. Треба влучити щонайменше по 4 цілях, щоб зрівнятися за шкодою з двома звичайними пострілами з довгого лука з <<Hunter's Mark|Мисливською міткою>>, а <<Hunter's Mark>> лишається корисною й після першого раунду, у який ви її наклали. Якщо ви користуєтеся цим заклинанням, треба вміти влучити по вражаюче великій кількості цілей, але навіть тоді воно рідко варте слота заклинань.",
    "block-section-spells-3-1/item/3": "<<Daylight>> ^^(^^[[1|PHB]]^^)^^: зазвичай досить <<Continual Flame|Вічного полумʼя>>, але іноді треба освітити більші площі, як-от темні поля бою чи величезні печери. Воно також розвіює магічну темряву 3-го рівня чи нижче, що чудово, якщо ви бʼєтеся з ворогами на кшталт дроу, що можуть створювати магічну темряву. На жаль, не можна накласти <<Daylight>> на вищому рівні, щоб розвіяти магічну темряву вищих рівнів.",
    "block-section-spells-3-1/item/4": "<<Elemental Weapon>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): це дає магічну зброю, схожу на заклинання <<Magic Weapon>>, але з більшим підсиленням шкоди. Це дуже добре лягає на звичну тактику Слідопита, але без витрат дії на постійне перепризначення <<Hunter's Mark|Мисливської мітки>>. <<Hunter's Mark>> дає трохи більший бонус до шкоди й триватиме довше, якщо накласти її з тим самим слотом, але не дає бонусу до кидків атаки, який кратно покращує ваш DPR. Навіть коли накласти це як заклинання 5-го рівня, воно лишається чудовим вибором, що перевершує DPR <<Swift Quiver|Швидкого сагайдака>>, навіть якщо ви користуєтеся зброєю з великим кубиком шкоди на кшталт мушкета й застосовуєте <<q:Sharpshooter|Влучного стрільця>>.",
    "block-section-spells-3-1/item/5": "<<Flame Arrows>> ^^(^^[[1|EEPC]]^^)^^: за той самий слот заклинань можна накласти <<Hunter's Mark|Мисливську мітку>> із тривалістю 8 годин. <<Hunter's Mark>> дасть таку саму кількість шкоди плюс інші переваги заклинання. Єдина перевага <<Flame Arrows|Полумʼяних стріл>> над <<Hunter's Mark|Мисливською міткою>> у тому, що не треба витрачати бонусну дію на зміну цілі, але навіть тоді ви обмежені таким малим запасом боєприпасів, що тривалість 1 година видається безглуздою. Звісно, накладання <<Flame Arrows|Полумʼяних стріл>> коштує Дію (проти бонусної дії в <<Hunter's Mark|Мисливської мітки>>), тож тривалість 1 година дещо полегшує підготовку перед боєм, якщо ви все одно наполягаєте на тому, щоб марнувати на це слот заклинань.",
    "block-section-spells-3-1/item/6": "<<Lightning Arrow>> ^^(^^[[1|PHB]]^^)^^: по суті, краща версія <<Hail of Thorns|Граду шипів>>, але шкода рідко достатньо добра, щоб виправдати слот заклинань, тож приберігайте його для випадку, коли великий гурт ворогів стоїть на малій площі. 5 чи більше здається добрим числом.",
    "block-section-spells-3-1/item/7": "<<Meld into Stone>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): дуже ситуативне.",
    "block-section-spells-3-1/item/9": "<<Plant Growth>> ^^(^^[[1|PHB]]^^)^^: ситуативне. Поза звичайною пригодницькою діяльністю здатність збагачувати землю, удвічі збільшуючи врожайність, дуже корисна. Але D&D — це насамперед гра про пригоди, а варіант зробити зону рослин перерослою важливіший для більшості шукачів пригод. У більшості випадків <<Entangle>> спрацює добре, якщо вам просто треба сповільнити ворогів, але <<Plant Growth>> не закінчується, тож через ці рослини й далі важко пройти, доки хтось їх не розчистить (що може потребувати годин рубання й/або спалювання). Заклинання також не уточнює, що рослини ростуть уздовж землі чи поверхонь, тож {{за правилами як написано|RAW}} воно може створити сферу рослин, утворюючи надскладну місцевість, що сягає на 100 футів угору, потенційно поглинаючи літаючих ворогів. Математика зменшення швидкості від <<Plant Growth|Росту рослин>> вражає. Оскільки більшість істот мають швидкість близько 30 футів, рух зі швидкістю 1/4 означає, що вони можуть пройти одну клітинку 5 футів, а решта 10 футів руху нікуди їх не приведе (хіба що вони виконають Ривок чи щось таке). Джереми Кроуфорд пояснив, що <<Plant Growth|Ріст рослин>> [[2|не створює складної місцевості]], тож можливо, що складна місцевість накопичуватиметься з <<Plant Growth|Ростом рослин>>, але особисто я думаю, що задумано не так. <<Plant Growth>> зазначає, що «істота, яка рухається областю, мусить витрачати 4 фути руху за кожен 1 фут», а правило складної місцевості — що «рух на 1 фут по складній місцевості коштує 2 фути швидкості», і оскільки ці два твердження суперечать одне одному, я думаю, що слід використовувати той ефект, який більший, а не складати їх чи множити чи щось таке. Хоч у тексті заклинання про це не йдеться, схоже, що <<Plant Growth>> також перешкоджатиме огляду. Якщо ви перетворите доглянутий живопліт на півсферу надскладної місцевості радіусом 100 футів, на шляху явно достатньо речей, щоб крізь них було важко бачити. Це неминуче означало б, що істоти всередині області, імовірно, були б певною мірою приховані, тож не чекайте, що можна накласти <<Plant Growth>> на ворога, а потім кілька ходів поспіль обстрілювати його замовляннями, доки він не впаде. Проблемне обмеження <<Plant Growth|Росту рослин>> — потреба, щоб в області були рослини. Проте, схоже, немає жодних обмежень щодо того, скільки їх має бути чи наскільки великими вони мають бути (лише що вони мають бути «звичайними», що б це не означало), а де немає ясності, там є простір для витівок. Наприклад: ви можете носити з собою рослину в горщику й кидати її в область, щоб забезпечити рослинне життя, необхідне для заклинання. Такі рослини, як мʼята чи конюшина, вміщуються в малий горщик, а коли ви змушуєте їх рости, отримуєте гарне й пахуче поле надскладної місцевості. Якщо ваш Майстер глузує з ідеї 100-футових конюшинових ділянок, подумайте про те, щоб носити дерево бонсай чи якусь іншу рослину, що зазвичай дуже висока (хоч бонсай може не відповідати «звичайній», оскільки ми не знаємо, що тут означає це слово).",
    "block-section-spells-3-1/item/10": "<<Protection from Energy>> ^^(^^[[1|PHB]]^^)^^: украй важливий захисний варіант, але сподіваємося, що до цього рівня у вашій групі вже є повні заклинателі, які можуть його забезпечити.",
    "block-section-spells-3-1/item/11": "<<Revivify>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): надто добре, щоб відмовлятися. Його варто взяти кожному, хто може.",
    "block-section-spells-3-1/item/12": "<<Speak with Plants>> ^^(^^[[1|PHB]]^^)^^: ситуативне. Якщо вам потрібна інформація, <<Speak with Animals>> часто дасть ту саму інформацію, бо де є рослини, там зазвичай є й тварини. Якщо вам потрібна складна місцевість, <<Plant Growth>> краще й працює в тих самих сценаріях. Якщо ви зустрінете рослинних істот, <<Speak with Plants>> — по суті, ваш єдиний варіант, але я ніколи не бачив слідопита з достатньою Харизмою, щоб це мало значення.",
    "block-section-spells-3-1/item/13": "<<Summon Fey>> ^^(^^[[1|TCoE]]^^)^^ (необовʼязкове): варіанти виклику мало що покращують порівняно з <<Summon Beast|Викликом Звіра>>, і вони все одно не є добрим вибором для Слідопита. Для додаткової допомоги дивіться наш [[2|Практичний гайд із заклинань виклику]].",
    "block-section-spells-3-1/item/16": "<<Wind Wall>> ^^(^^[[1|PHB]]^^)^^: надто ситуативна. Зазвичай її використовують, щоб ворогам не вдалося стріляти по вас із дальньої зброї, але оскільки у вас недостатньо чаротворства, щоб покладатися на нього як на основний наступальний варіант, ви, імовірно, лише шкодите собі, хіба що повністю не здатні користуватися дальньою зброєю.",

    "block-section-spells-4-1/item/0": "<<Conjure Woodland Beings>> ^^(^^[[1|PHB]]^^)^^: зазвичай це чудове заклинання, але Слідопит отримує його так пізно, що воно цілком застаріле.",
    "block-section-spells-4-1/item/1": "<<Dominate Beast>> ^^(^^[[1|PHB]]^^)^^: до того часу, як ви зможете його накласти, звірі вже перестали бути загрозою.",
    "block-section-spells-4-1/item/3": "<<Grasping Vine>> ^^(^^[[1|PHB]]^^)^^: не добре заклинання, ваша СК ряткидка буде відносно поганою, а бонусна дія вам потрібна для інших речей.",
    "block-section-spells-4-1/item/4": "<<Guardian of Nature>>: можливо, єдиний варіант, доступний слідопитам, у якому Сила виглядає спокусливо. <<Guardian of Nature>> робить вас справді сильним на 1 хвилину. Варіант «Первісний звір»{{Primal Beast}} робить вас дуже добрим у нападі, але Перевага на кубику на атаки на основі Сили свідчить, що він призначений для збірок на Силі, які для Слідопита зазвичай жахливі. Варіант «Велике дерево»{{Great Tree}} дає Перевагу на кубику на кидки атаки на основі Спритності (імовірно, найважливіша для вас частина), але також Перевагу на кубику на ряткидки Статури, тож ви рідше втрачатимете Концентрацію, а ще складну місцевість у зоні, тож ворогам буде важко входити в ближній бій із вами й виходити з нього.",
    "block-section-spells-4-1/item/7": "<<Summon Elemental>> ^^(^^[[1|TCoE]]^^)^^ (необовʼязкове): ви отримуєте це надто пізно, щоб воно було життєздатним у бою, а утилітарної користі тут небагато. Для додаткової допомоги дивіться наш [[2|Практичний гайд із заклинань виклику]].",

    "block-section-spells-5-1/item/0": "<<Commune With Nature>> ^^(^^[[1|PHB]]^^)^^: було б значно краще, якби ви могли накладати ритуали.",
    "block-section-spells-5-1/item/1": "<<Conjure Volley>> ^^(^^[[1|PHB]]^^)^^: це робить уміння <<q:Volley|Залп>> Слідопита-Мисливця дещо надлишковим, але це не робить заклинання добрим варіантом. Воно має всі ті самі проблеми, що й у <<Conjure Barrage|Виклику обстрілу>>. Ваша СК ряткидка буде відносно низькою, якщо ви не вклалися повністю в Мудрість після досягнення Спритності 20, тож більшість слідопитів можуть очікувати, що вороги часто проходитимуть ряткидок.",
    "block-section-spells-5-1/item/2": "<<Greater Restoration>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): украй важливий варіант лікування, але якщо ваша група дожила до цього рівня, у вас майже напевно вже є до нього доступ, і вам не доведеться вивчати його назавжди.",
    "block-section-spells-5-1/item/3": "<<Steel Wind Strike>> ^^(^^[[1|XGtE]]^^)^^: якби це була атака ближньою зброєю, а не заклинальна атака ближнього бою, воно було б чудовим, але ваші заклинальні атаки, імовірно, трохи відстають від атак зброєю, тож ви, швидше за все, промахнетеся, якщо щось інше не додає до ваших атак, як-от <<Guardian of Nature>> чи <<Bless>>.",
    "block-section-spells-5-1/item/4": "<<Swift Quiver>> ^^(^^[[1|PHB]]^^)^^: величезно покращує вашу економіку дій, але оскільки воно вимагає Концентрації, його не можна поєднувати з <<Hunter's Mark|Мисливською міткою>> чи <<Guardian of Nature|Вартовим природи>>, і воно потребує дальньої зброї з боєприпасами, тож слідопити на Силі не мають доброго способу ним користуватися. Воно також робить <<q:Crossbow Expert|Експерта з арбалетів>> дещо надлишковим, а залежно від кількох змінних (магічна зброя, можливо, інші бафи тощо) ви можете завдавати більше шкоди з <<Hunter's Mark|Мисливською міткою>> і Експертом з арбалетів, ніж з одним додатковим пострілом із дальньої зброї без додаткового к6 шкоди. Розгляньмо слідопита високого рівня з Експертом з арбалетів, немагічним ручним арбалетом і Спритністю 20. 4 атаки завдадуть сумарно 4к6+20 (у середньому 36), тоді як три атаки з активною <<Hunter's Mark|Мисливською міткою>> завдадуть 6к6+15 (у середньому 36). У математиці є певні нюанси, бо додаткова атака означає ще один шанс завдати Критичного влучання, але різниця недостатньо велика, щоб виправдати те, що <<Swift Quiver>> — заклинання 5-го рівня, коли <<Hunter's Mark|Мисливську мітку>> можна накласти як заклинання 1-го рівня. Магічна зброя, риси чи класові уміння, що додають додаткову шкоду, схилять математику на бік <<Swift Quiver|Швидкого сагайдака>> значно сильніше, але я не певен, скільки треба, щоб виправдати різницю в рівні заклинання між <<Hunter's Mark|Мисливською міткою>> і <<Swift Quiver|Швидким сагайдаком>>. Тепер розгляньмо того самого слідопита з довгим луком і без Експерта з арбалетів. Для нього дві додаткові атаки подвоюють кількість атак за хід, піднімаючи його шкоду з 2к8+2к6+10 із <<Hunter's Mark|Мисливською міткою>> (у середньому 26) до 4к8+20 (у середньому 38), тобто майже на 50% більше шкоди. Ми знову ігноруємо можливість Критичних влучань, бойовий стиль, магічні предмети тощо, але будь-що з цього ще сильніше схиляє математику на користь <<Swift Quiver|Швидкого сагайдака>>. Навіть якщо ви побудовані для ближнього бою, <<Swift Quiver>> — чудовий спосіб перейти на дальній бій і завдати купу шкоди.",
    "block-section-spells-5-1/item/5": "<<Tree Stride>> ^^(^^[[1|PHB]]^^)^^: ситуативне. У бою задум у тому, що ви використаєте це, щоб перехитрити ворогів, переміщаючись між деревами, але для цього потрібна велика кількість доступних дерев. Попри те, як сильно D&D любить ліси, вони становлять крихітну частку загального ландшафту пригод, тож не можна гарантувати, що це колись стане корисним у більшості кампаній.",
    "block-section-spells-5-1/item/6": "<<Wrath of Nature>> ^^(^^[[1|XGtE]]^^)^^: захопливе, але корисність заклинання залежить від рясноти рослинного життя в області. Було б краще, якби можна було замінювати частини заклинання під довкілля, але якщо ви в пустелі чи замерзлій тундрі, можете не отримати нічого. Як виправлення: дозвольте структурно схожому рослинному життю замінювати рослини, зазначені в описі заклинання: нехай водорості працюють як лози, великі кактуси чи гігантські гриби — як дерева тощо.",

    "block-section-11-1": "Слідопити можуть замінювати одне відоме заклинання щоразу, коли здобувають рівень Слідопита.",
    "block-section-12-1": "Слідопити зазвичай не вивчають замовлянь, але можуть вивчити два замовляння, взявши бойовий стиль <<q:Druidic Warrior>>.",
    "block-section-13-1": "Слідопити знають два заклинання 1-го рівня, починаючи з 2-го рівня, але на 20-му рівні знатимуть до 11 заклинань.",
    "block-section-14-1": "Слідопити накладають заклинання, використовуючи Мудрість. Для матеріальних компонентів вони можуть користуватися {{сумкою з компонентами|component pouch}}, але не можуть користуватися чаротворчими фокусами{{spellcasting focuses}}.",
}

FRAGMENTS = refs.expand_all(FRAGMENTS)
